+  /* stable under repeated recomputation */
+  affect_total(&fixture.ch);
+  limb_reconcile(&fixture.ch);
+  CuAssertIntEquals(tc, 10, count_carried(&fixture.ch));
+
+  end_four_arm_fixture(&fixture);
+}
