+static struct obj_data round_plan_offhand;
+
+static void wield_round_plan_offhand(struct four_arm_combat_fixture *fixture)
+{
+  equip_char(&fixture->actor, &round_plan_offhand, WEAR_WIELD_OFFHAND);
+}
